uniform vec2 iResolution;
uniform float iTime;
uniform shader composable;
uniform float uSpeed;              // min: 0.1, max: 5.0, default: 0.40000, 회전 속도
uniform float uRectWidth;          // min: 0.1, max: 2.0, default: 0.70000, 사각형 가로 크기
uniform float uRectHeight;         // min: 0.1, max: 2.0, default: 0.70000, 사각형 세로 크기
uniform float uSquirclePower;      // min: 2.0, max: 8.0, default: 5.20000, Squircle 곡률 (높을수록 각짐)
uniform float uMarginHorizontal;   // min: 0.0, max: 0.5, default: 0.00000, 좌우 마진
uniform float uMarginVertical;     // min: 0.0, max: 0.5, default: 0.00000, 상하 마진
uniform float uThickness;          // min: 0.01, max: 0.2, default: 0.05000, 기본 두께(중앙 기준)
uniform float uTailLength;         // min: 0.1, max: 1.0, default: 0.50000, 꼬리 길이 (0~1)
uniform float uFeather;            // min: 0.0, max: 1.0, default: 0.20000, 가장자리 부드러움
uniform float uSegments;           // min: 5, max: 50, default: 30.00000, 꼬리 세그먼트 수
uniform vec3 uColor1;             // min: [0.0, max: [1.0, default: [1.00000, 0.55294, 0.47843], 꼬리1 색상1 (#FF8D7A)
uniform vec3 uColor2;             // min: [0.0, max: [1.0, default: [0.76078, 0.69804, 1.00000], 꼬리1 색상2 (#C2B2FF)
uniform float uColor1Weight;       // min: 0.0, max: 3.0, default: 1.00000, 첫 번째 색상 비중
uniform float uColor2Weight;       // min: 0.0, max: 3.0, default: 1.00000, 두 번째 색상 비중
uniform float uAlpha;              // min: 0.0, max: 1.0, default: 1.00000, 전체 투명도
uniform float uColorBlend;         // min: 0.05, max: 0.5, default: 0.20000, 색상 전환 부드러움
uniform float uBrightness;         // min: -1.0, max: 1.0, default: 0.00000, 밝기 조절
uniform float uContrast;           // min: 0.0, max: 3.0, default: 1.00000, 대비 조절
uniform float uSaturation;         // min: 0.0, max: 3.0, default: 1.00000, 채도 조절
uniform float uHeadThin;           // min: 0.2, max: 1.0, default: 0.20000, 헤드 최소 두께 비율
uniform float uTailThin;           // min: 0.00, max: 0.80, default: 0.00000, 꼬리 끝 최소 두께 비율
uniform float uTailFadePow;        // min: 0.5, max: 4.0, default: 0.50000, 꼬리 밝기 감소 곡률
uniform vec3 u2Color1;            // min: [0.0, max: [1.0, default: [0.54510, 0.74118, 1.00000], 꼬리2 색상1 (#8BBDFF)
uniform vec3 u2Color2;            // min: [0.0, max: [1.0, default: [0.53333, 0.90196, 0.89020], 꼬리2 색상2 (#88E6E3)
uniform float u2Color1Weight;      // min: 0.0, max: 3.0, default: 1.00000, 세 번째 색상 비중
uniform float u2Color2Weight;      // min: 0.0, max: 3.0, default: 1.00000, 네 번째 색상 비중
uniform float u2Alpha;             // min: 0.0, max: 3.0, default: 1.20000, 두 번째 꼬리 알파
vec2 getSquirclePoint(float t, vec2 size, float n) {
    t = fract(t);
    float angle = t * 6.28318530718;

    float halfW = size.x * 0.5;
    float halfH = size.y * 0.5;

    float cosA = cos(angle);
    float sinA = sin(angle);

    float absCosA = max(abs(cosA), 0.0001);
    float absSinA = max(abs(sinA), 0.0001);

    float powCos = pow(absCosA, n);
    float powSin = pow(absSinA, n);

    float denom = max(pow(powCos + powSin, 1.0 / n), 0.0001);

    float x = halfW * sign(cosA) * absCosA / denom;
    float y = halfH * sign(sinA) * absSinA / denom;

    return vec2(x, y);
}

vec2 distToSegment(vec2 p, vec2 a, vec2 b) {
    vec2 ab = b - a;
    float len2 = dot(ab, ab);
    float valid = step(0.0001, len2);
    float t = clamp(dot(p - a, ab) / max(len2, 0.0001), 0.0, 1.0);
    vec2 proj = a + t * ab;
    float d = distance(p, proj);
    return mix(vec2(distance(p, a), 0.0), vec2(d, t), valid);
}

float taperedThickness(float p) {
    float head = mix(uHeadThin, 1.0, smoothstep(0.00, 0.35, p));
    float tail = mix(1.0, uTailThin, smoothstep(0.55, 1.00, p));
    float bell = clamp(1.0 - abs(p - 0.50) * 1.6, 0.0, 1.0);
    float profile = head * tail * bell;
    return uThickness * clamp(profile, 0.0, 1.0);
}

float tailBrightness(float p) { 
    return pow(1.0 - p, uTailFadePow); 
}

vec3 rampColor(float phase, vec3 c1, vec3 c2, float w1, float w2) {
    float totalWeight = max(w1 + w2, 0.001);
    float ratio1 = w1 / totalWeight;
    float t = fract(phase);

    // 중앙 전환: ratio1 위치에서 c1→c2
    float blend1to2 = smoothstep(ratio1 - uColorBlend, ratio1 + uColorBlend, t);

    // wrap 전환: 1.0 위치에서 c2→c1 (다음 사이클로 순환)
    float blend2to1 = smoothstep(1.0 - uColorBlend, 1.0, t);

    // 최종 블렌드: ratio1 근처는 blend1to2, 1.0 근처는 blend2to1
    float finalBlend = blend1to2 * (1.0 - blend2to1);

    vec3 color = mix(c1, c2, finalBlend);
    return color;
}

float computeEdge(float dist, float thick, float feather) {
    float featherWidth = thick * feather;
    float innerEdge = thick - featherWidth;
    float outerEdge = thick + featherWidth * 0.5;
    return 1.0 - smoothstep(innerEdge, outerEdge, dist);
}

vec3 adjustColor(vec3 color) {
    color = color + uBrightness;
    color = (color - 0.5) * uContrast + 0.5;
    float luminance = dot(color, vec3(0.299, 0.587, 0.114));
    color = mix(vec3(luminance), color, uSaturation);
    return clamp(color, 0.0, 1.0);
}

vec4 main(vec2 fragCoord)
{

    // Y 방향 반전
    vec2 uv = fragCoord / iResolution.xy;

    vec2 marginMin = vec2(uMarginHorizontal, uMarginVertical);
    vec2 marginMax = vec2(1.0 - uMarginHorizontal, 1.0 - uMarginVertical);
    vec2 validSize = marginMax - marginMin;
    vec2 center = (marginMin + marginMax) * 0.5;

    float aspect = iResolution.x / iResolution.y;
    vec2 adjustedSize = vec2(uRectWidth, uRectHeight);
    adjustedSize.x *= validSize.x;
    adjustedSize.y *= validSize.y;

    if (aspect > 1.0) {
        adjustedSize.x *= aspect;
    } else {
        adjustedSize.y /= aspect;
    }

    vec2 pos = uv - center;
    if (aspect > 1.0) {
        pos.x *= aspect;
    } else {
        pos.y /= aspect;
    }

    float baseTime = iTime * uSpeed;

    vec3  accColor = vec3(0.0);
    float accAlpha = 0.0;

    int segCount = int(uSegments);
    const int maxLoop = 50;

    // --- Tail #1 ---
    float minDist1 = 1e10;
    float bestP1 = 0.0;
    float bestTInterp1 = 0.0;
    float bestThick1 = 0.0;

    for (int i = 0; i < maxLoop; i++) {
        if (i >= segCount) break;

        float t0 = float(i) / float(segCount) * uTailLength;
        float t1 = float(i + 1) / float(segCount) * uTailLength;

        vec2 p0 = getSquirclePoint(baseTime - t0, adjustedSize, uSquirclePower);
        vec2 p1 = getSquirclePoint(baseTime - t1, adjustedSize, uSquirclePower);

        vec2 segResult = distToSegment(pos, p0, p1);
        float d = segResult.x;
        float segT = segResult.y;

        float tInterp = mix(t0, t1, segT);
        float p = tInterp / uTailLength;
        float thick = taperedThickness(p);

        if (d < minDist1) {
            minDist1 = d;
            bestP1 = p;
            bestTInterp1 = tInterp;
            bestThick1 = thick;
        }
    }

    float outerLimit1 = bestThick1 * (1.0 + uFeather * 0.5);
    if (minDist1 < outerLimit1) {
        vec3 col = rampColor(baseTime - bestTInterp1 + 0.25, uColor1, uColor2, uColor1Weight, uColor2Weight);
        col = adjustColor(col);
        float edge = computeEdge(minDist1, bestThick1, uFeather);
        float a = edge;
        accColor += col * a;
        accAlpha = max(accAlpha, a);
    }

    // --- Tail #2 ---
    float oppositeTime = baseTime + 0.5;
    float minDist2 = 1e10;
    float bestP2 = 0.0;
    float bestTInterp2 = 0.0;
    float bestThick2 = 0.0;

    for (int i = 0; i < maxLoop; i++) {
        if (i >= segCount) break;

        float t0 = float(i) / float(segCount) * uTailLength;
        float t1 = float(i + 1) / float(segCount) * uTailLength;

        vec2 p0 = getSquirclePoint(oppositeTime - t0, adjustedSize, uSquirclePower);
        vec2 p1 = getSquirclePoint(oppositeTime - t1, adjustedSize, uSquirclePower);

        vec2 segResult = distToSegment(pos, p0, p1);
        float d = segResult.x;
        float segT = segResult.y;

        float tInterp = mix(t0, t1, segT);
        float p = tInterp / uTailLength;
        float thick = taperedThickness(p);

        if (d < minDist2) {
            minDist2 = d;
            bestP2 = p;
            bestTInterp2 = tInterp;
            bestThick2 = thick;
        }
    }

    float outerLimit2 = bestThick2 * (1.0 + uFeather * 0.5);
    if (minDist2 < outerLimit2) {
        vec3 col = rampColor(oppositeTime - bestTInterp2 + 0.25, u2Color1, u2Color2, u2Color1Weight, u2Color2Weight);
        col = adjustColor(col);
        float edge = computeEdge(minDist2, bestThick2, uFeather);
        float a = edge * tailBrightness(bestP2) * u2Alpha;
        accColor += col * a;
        accAlpha = max(accAlpha, a);
    }

    accColor = clamp(accColor, 0.0, 1.0);
return vec4(accColor, clamp(accAlpha, 0.0, 1.0));

}

