uniform vec2 iResolution;
uniform float iTime;
uniform shader composable;
uniform float radiusX; // min: 0.0, max: 0.1, default: 0.01500, 0.05 = 화면의 5%)
uniform float radiusY; // min: 0.0, max: 0.1, default: 0.01500, 0.05 = 화면의 5%)
int uSampleCount = 9; //min: 5, max: 25, default: 15, 블러 샘플 개수 (홀수 권장)
