uniform float iTime;
uniform shader composable;
uniform float uSaturation; // min: 0.0, max: 2.0, default: 1.4, 2: 과포화)
uniform float uBrightness; // min: -1.0, max: 1.0, default: 0.0, 1: 완전 밝음)
uniform float uContrast; // min: 0.0, max: 2.0, default: 1.0, 2: 강한 대비)
vec4 main(vec2 fragCoord)
{

    // Y 방향 반전
    vec2 uv = fragCoord / iResolution.xy;

    vec4 texColor = composable.eval(uv * iResolution.xy);
    vec3 color = texColor.rgb;

    // 밝기 조절
    color = color + uBrightness;

    // 명도 대비 조절
    color = (color - 0.5) * uContrast + 0.5;

    // 채도 조절
    float luminance = dot(color, vec3(0.299, 0.587, 0.114));
    color = mix(vec3(luminance), color, uSaturation);

    // 0~1 범위로 클램핑
    color = clamp(color, 0.0, 1.0);

return vec4(color, texColor.a);

}

